CREATE TABLE "student_directory" (
	"email" varchar PRIMARY KEY NOT NULL,
	"full_name" varchar NOT NULL,
	"batch" integer,
	"source" varchar DEFAULT 'mess-2026-03' NOT NULL
);
--> statement-breakpoint
CREATE INDEX "student_directory_name_idx" ON "student_directory" USING btree ("full_name");
--> statement-breakpoint
-- Generated by scripts/build-student-seed.ts from the March 2026 mess register.
-- Do not hand-edit: regenerate from the PDF instead.
--
-- 4122 students. ERP IDs are 411 + the eight digits of the BITS
-- email local part, so 41120250558 -> f20250558@hyderabad.bits-pilani.ac.in.
--
-- Skipped on purpose: the 216 rows with a 412 prefix (higher degree, a
-- different email letter we have not confirmed) and one malformed 111 row.
-- Nobody skipped is unreachable -- they just have to sign in once before a POR
-- can add them, the same as any day scholar the mess register never listed.
--
-- Names are the register's, normalised to caps. Deliberately not title-cased:
-- it turns VIGNESH CK into Vignesh Ck and ZAHED RIYAZ K S into Zahed Riyaz K S.
-- search_students prefers profiles.full_name from Google once a student signs in.

on conflict (email) do update
  set full_name = excluded.full_name,
      batch     = excluded.batch,
      source    = excluded.source;

